Repo /luxon (Luxon JS library, jest tests). BUG: `Interval.fromISO` in src/interval.js does not work when `Settings.throwOnInvalid` is true: it calls `DateTime.fromISO(s, opts)` / `DateTime.fromISO(e, opts)` directly, and with throwOnInvalid those throw for the duration part of strings like "2016-01-01/P1Y" or "P1Y/2016-01-01", so valid intervals can't be parsed. FIX (edit only src/interval.js): rewrite `static fromISO(text, opts)` so that each `DateTime.fromISO(...)` call is wrapped in its own try/catch, setting `startIsValid`/`endIsValid` to false when it throws, e.g.

  static fromISO(text, opts) {
    const [s, e] = (text || "").split("/", 2);
    if (s && e) {
      let start, startIsValid;
      try {
        start = DateTime.fromISO(s, opts);
        startIsValid = start.isValid;
      } catch (err) {
        startIsValid = false;
      }
      let end, endIsValid;
      try {
        end = DateTime.fromISO(e, opts);
        endIsValid = end.isValid;
      } catch (err) {
        endIsValid = false;
      }
      if (startIsValid && endIsValid) {
        return Interval.fromDateTimes(start, end);
      }
      if (startIsValid) {
        const dur = Duration.fromISO(e, opts);
        if (dur.isValid) {
          return Interval.after(start, dur);
        }
      } else if (endIsValid) {
        const dur = Duration.fromISO(s, opts);
        if (dur.isValid) {
          return Interval.before(end, dur);
        }
      }
    }
    return Interval.invalid("unparsable", `the input "${text}" can't be parsed as ISO 8601`);
  }

Also fix the typo in the invalid explanation string: it currently says `can't be parsed asISO 8601` and must say `can't be parsed as ISO 8601` (space after "as"). Keep everything else identical. VERIFY: (a) create a temporary test file /luxon/test/interval/tmp-throw.test.js containing:

/* global test expect */
import { Interval, Settings } from "../../src/luxon";
const withThrowOnInvalid = (v, f) => { const old = Settings.throwOnInvalid; Settings.throwOnInvalid = v; try { f(); } finally { Settings.throwOnInvalid = old; } };
test("Interval.fromISO works with Settings.throwOnInvalid", () => {
  withThrowOnInvalid(true, () => {
    expect(() => Interval.fromISO("2016-01-01/2016-12-31")).not.toThrow();
    expect(() => Interval.fromISO("2016-01-01/P1Y")).not.toThrow();
    expect(() => Interval.fromISO("P1Y/2016-01-01")).not.toThrow();
    expect(() => Interval.fromISO("2016-01-01/hello")).toThrow();
    expect(() => Interval.fromISO("hello/2016-01-01")).toThrow();
    expect(() => Interval.fromISO("hello")).toThrow();
  });
});

run `cd /luxon && npx jest test/interval` and make it pass, then DELETE the temporary test file. (b) Run the whole suite `cd /luxon && npx jest 2>&1 | tail -40`. The ONLY pre-existing failures allowed are 2 tests in test/datetime/toFormat.test.js related to French locale/ICU. Report: exact edits made, the temp-test result, the full-suite pass/fail counts, and any newly failing test names. Do not modify any test file that already existed, and do not touch files other than src/interval.js.

Repo /luxon (Luxon JS library, jest). Two independent bugs in src/impl/util.js. Edit ONLY src/impl/util.js.

BUG A: `objToLocalTS(obj)` mishandles years 0-99. It currently does Date.UTC(obj.year, ...) (which JS interprets as 19xx) and then subtracts 1900 from the resulting year. Because 1900-1999 has a different leap-year structure than years 0-99, month/day overflow normalization is wrong: e.g. `DateTime.fromISO("0099-12-31", {zone:"utc"}).plus({ days: 61 })` must be 0100-03-02 but currently yields 0100-03-01. FIX: shift such years by 400 (a full Gregorian cycle, so leap years line up exactly) instead of 1900. Replace the whole function with:

export function objToLocalTS(obj) {
  // for legacy reasons, years between 0 and 99 are interpreted as 19XX by Date.UTC;
  // shift them by 400 years (a full Gregorian cycle, so leap years line up) and
  // shift back after the month/day overflow has been normalized
  const year = obj.year < 100 && obj.year >= 0 ? obj.year + 400 : obj.year;
  let d = Date.UTC(
    year,
    obj.month - 1,
    obj.day,
    obj.hour,
    obj.minute,
    obj.second,
    obj.millisecond
  );

  if (year !== obj.year) {
    d = new Date(d);
    d.setUTCFullYear(d.getUTCFullYear() - 400);
  }
  return +d;
}

BUG B: `padStart(input, n = 2)` does not pad negative numbers: it returns ("0".repeat(n) + input).slice(-n), so year -100 formatted with "yyyy" gives "-100" instead of "-0100" (and -1 gives "000-1"). FIX: replace it with

export function padStart(input, n = 2) {
  const isNeg = input < 0;
  let padded;
  if (isNeg) {
    padded = "-" + ("" + -input).padStart(n, "0");
  } else {
    padded = ("" + input).padStart(n, "0");
  }
  return padded;
}

VERIFY: (a) create a temporary test file /luxon/test/datetime/tmp-probe.test.js with:

/* global test expect */
import { DateTime } from "../../src/luxon";
test("plus across 100 barrier through February", () => {
  const d = DateTime.fromISO("0099-12-31", { zone: "utc" }).plus({ days: 61 });
  expect([d.year, d.month, d.day]).toEqual([100, 3, 2]);
  const d2 = DateTime.fromISO("0099-12-31", { zone: "utc" }).plus({ months: 2 });
  expect([d2.year, d2.month, d2.day]).toEqual([100, 2, 28]);
  const d3 = DateTime.fromISO("0099-12-31", { zone: "utc" }).plus({ days: 60 });
  expect([d3.year, d3.month, d3.day]).toEqual([100, 3, 1]);
  const d4 = DateTime.fromISO("0100-01-02", { zone: "utc" }).minus({ days: 2 });
  expect([d4.year, d4.month, d4.day]).toEqual([99, 12, 31]);
});
test("toISODate pads negative years", () => {
  expect(DateTime.fromObject({ year: -100, month: 1, day: 1 }).toISODate()).toBe("-0100-01-01");
  expect(DateTime.fromObject({ year: -1, month: 1, day: 1 }).toISODate()).toBe("-0001-01-01");
  expect(DateTime.fromObject({ year: 1, month: 1, day: 1 }).toISODate()).toBe("0001-01-01");
});

