Repo /luxon (Luxon JS library, jest). BUG in src/duration.js: in the `casualMatrix` unit-conversion table (top of the file, around lines 30-59) the `quarters` entry is missing its `seconds` conversion:

      quarters: {
        months: 3,
        weeks: 13,
        days: 91,
        hours: 91 * 24,
        minutes: 91 * 24 * 60,
        milliseconds: 91 * 24 * 60 * 60 * 1000
      },

so converting between quarters and seconds yields NaN (e.g. `Duration.fromObject({ quarters: 1 }).as("seconds")` or `.shiftTo("seconds")`). FIX: add the missing line `seconds: 91 * 24 * 60 * 60,` between the `minutes` and `milliseconds` lines of that `quarters` object. Do not change anything else in the file (the accurateMatrix already has all entries).

VERIFY: (a) create a temporary test file /luxon/test/duration/tmp-normalize.test.js with:

/* global test expect */
import { Duration } from "../../src/luxon";
test("Duration#normalize can convert all unit pairs", () => {
  const units = ["years", "quarters", "months", "weeks", "days", "hours", "minutes", "seconds", "milliseconds"];
  for (const u1 of units) {
    for (const u2 of units) {
      const dur = Duration.fromObject({ [u1]: 1 });
      const as = dur.as(u2);
      expect(Number.isNaN(as)).toBe(false);
      const shifted = dur.shiftTo(u2);
      expect(shifted.isValid).toBe(true);
      expect(shifted.get(u2)).not.toBeUndefined();
      const norm = Duration.fromObject({ [u1]: 1, [u2]: 1 }).normalize();
      expect(norm.isValid).toBe(true);
      for (const k of Object.keys(norm.toObject())) {
        expect(Number.isNaN(norm.toObject()[k])).toBe(false);
      }
    }
  }
});

