Repo /luxon (Luxon JS library, jest). BUG in src/datetime.js: the `isInDST` getter (around line 1164) is

  get isInDST() {
    if (this.isOffsetFixed) {
      return false;
    } else {
      return (
        this.offset > this.set({ month: 1 }).offset || this.offset > this.set({ month: 5 }).offset
      );
    }
  }

This compares against the same day-of-month in January and May, which is wrong in years where DST starts in early January, notably the USA in 1974 (DST ran from January 6 to October 27, 1974): for e.g. 1974-06-15 in America/New_York both reference offsets are already DST (-240), so isInDST wrongly returns false. FIX: compare against the 1st of January and the 1st of May instead:

  get isInDST() {
    if (this.isOffsetFixed) {
      return false;
    } else {
      return (
        this.offset > this.set({ month: 1, day: 1 }).offset ||
        this.offset > this.set({ month: 5, day: 1 }).offset
      );
    }
  }

Edit ONLY src/datetime.js and only that getter. VERIFY: (a) create a temporary test file /luxon/test/datetime/tmp-dst.test.js with:

/* global test expect */
import { DateTime } from "../../src/luxon";
test("DateTime#isInDST() returns true for 1974 whole year in USA- from January 6th to October 27th", () => {
  const start = DateTime.fromISO("1974-01-06T00:00:00", { zone: "America/New_York" });
  const end = DateTime.fromISO("1974-10-27T00:00:00", { zone: "America/New_York" });
  expect(start.isInDST).toBe(true);
  expect(end.isInDST).toBe(true);
  expect(DateTime.fromISO("1974-06-15T12:00:00", { zone: "America/New_York" }).isInDST).toBe(true);
  expect(DateTime.fromISO("1974-01-05T12:00:00", { zone: "America/New_York" }).isInDST).toBe(false);
  expect(DateTime.fromISO("1974-10-28T12:00:00", { zone: "America/New_York" }).isInDST).toBe(false);
  expect(DateTime.fromISO("1982-05-25T04:00:00", { zone: "America/Los_Angeles" }).isInDST).toBe(true);
  expect(DateTime.fromISO("1982-01-25T04:00:00", { zone: "America/Los_Angeles" }).isInDST).toBe(false);
  expect(DateTime.fromISO("1982-12-25T04:00:00", { zone: "America/Los_Angeles" }).isInDST).toBe(false);
  expect(DateTime.utc().isInDST).toBe(false);
});

